#!/usr/bin/env python3
"""Independent validator: reads ONLY input/output files + provided cost_model."""
import json, sys
sys.path.insert(0, '/app/task_file/scripts')
from cost_model import CostModel, align, HEADS, HIDDEN

ROOT = '/app/task_file'
LIMITS = {
    '1': {'cost': 3.0e11, 'pad_ratio': 0.055, 'p95_latency_ms': 2.1e6, 'sequential_timecost': 2.7e8},
    '2': {'cost': 4.8e10, 'pad_ratio': 0.15, 'p95_latency_ms': 2.1e5, 'sequential_timecost': 3.2e7},
}
GRAN = 64

def jl(p):
    return [json.loads(l) for l in open(p)]

ok_all = True
global_shapes = set()
for name in ['1', '2']:
    reqs = jl(f'{ROOT}/input_data/requests_bucket_{name}.jsonl')
    plan = jl(f'{ROOT}/output_data/plan_b{name}.jsonl')
    reqmap = {r['request_id']: r for r in reqs}
    errs = []

    # 1. exactly once
    ids = [p['request_id'] for p in plan]
    if len(ids) != len(set(ids)):
        errs.append('duplicate request_id')
    if set(ids) != set(reqmap):
        errs.append(f'missing={len(set(reqmap)-set(ids))} extra={len(set(ids)-set(reqmap))}')

    # 2. per-batch shape consistency + shape validity
    batch_shape = {}
    for p in plan:
        sh = p['shape']
        sa, ha, hid = int(sh['seq_align']), int(sh['heads_align']), int(sh['hidden_align'])
        if ha != HEADS or hid != HIDDEN:
            errs.append(f"bad heads/hidden {ha},{hid}")
        if sa % GRAN != 0:
            errs.append(f'seq_align {sa} not multiple of {GRAN}')
        need = align(reqmap[p['request_id']]['prompt_len'], GRAN)
        if sa < need:
            errs.append(f"seq_align {sa} < required {need} for {p['request_id']}")
        if p['batch_id'] in batch_shape and batch_shape[p['batch_id']] != (sa, ha, hid):
            errs.append(f"shape mismatch in batch {p['batch_id']}")
        batch_shape[p['batch_id']] = (sa, ha, hid)

    shapes = set(batch_shape.values())
    global_shapes |= shapes
    if len(shapes) > 8:
        errs.append(f'too many unique shapes: {len(shapes)}')

    m = CostModel(GRAN).plan_metrics(reqmap, plan)
    print(f'=== bucket {name}: requests={len(reqs)} plan_rows={len(plan)} batches={len(batch_shape)} unique_shapes={len(shapes)}')
    for k, lim in LIMITS[name].items():
        v = m[k]
        good = v <= lim
        if not good:
            errs.append(f'{k} {v:.4e} > {lim:.4e}')
        print(f'   {k:22s} {v:.6e} <= {lim:.3e}  {"OK" if good else "FAIL"}')
    if errs:
        ok_all = False
        print('   ERRORS:', errs)
    else:
        print('   VALID')

print(f'\nUnique shapes across BOTH buckets: {sorted(global_shapes)} (n={len(global_shapes)})')
ok_all &= len(global_shapes) <= 8
print('ALL VALID' if ok_all else 'FAILURES PRESENT')
sys.exit(0 if ok_all else 1)
